INSERT INTO bnd_boundary_kind (code, label, definition) VALUES ('AuthorizationBoundary', 'Authorization boundary', 'All the components of an information system that one authorizing official authorizes to operate; separately authorized systems it is connected to are outside it.');
INSERT INTO bnd_boundary_kind (code, label, definition) VALUES ('CuiEnvironment', 'CUI environment', 'The assessment scope of an organization that handles controlled unclassified information: the assets that process, store or transmit it, the ones that protect them and the ones the organization''s own practice keeps from it.');
INSERT INTO bnd_boundary_kind (code, label, definition) VALUES ('EphiEnvironment', 'ePHI environment', 'The systems, people and services through which a covered entity or a business associate creates, receives, maintains or transmits electronic protected health information.');
INSERT INTO bnd_boundary_kind (code, label, definition) VALUES ('CardholderDataEnvironment', 'Cardholder data environment', 'The system components, people and processes that store, process or transmit cardholder data or sensitive authentication data, and the components that are connected to them without restriction.');
INSERT INTO bnd_boundary_kind (code, label, definition) VALUES ('Soc2System', 'SOC 2 system', 'The system a service organization''s report describes: its services, components, controls and the boundaries of what the description covers, with its subservice organizations.');
INSERT INTO bnd_boundary_kind (code, label, definition) VALUES ('Privacy', 'Privacy boundary', 'The personal data and the processing activities that one controller or business answers for under one privacy regime.');
INSERT INTO bnd_boundary_kind (code, label, definition) VALUES ('Organizational', 'Organizational boundary', 'What one company, legal entity, tenant or client of a provider of managed services owns or answers for, or a part of it.');
INSERT INTO bnd_boundary_kind (code, label, definition) VALUES ('NetworkZone', 'Network zone', 'A set of resources inside one common perimeter, joined to other zones only through managed interfaces: an enclave, a segment or a zone.');
INSERT INTO bnd_boundary_kind (code, label, definition) VALUES ('Trust', 'Trust boundary', 'A line of a threat model across which data or control passes between parts that are trusted differently.');
INSERT INTO bnd_boundary_kind (code, label, definition) VALUES ('EngagementScope', 'Engagement scope', 'The targets, actions and window that a signed engagement allows, and the targets that are off limits.');
INSERT INTO bnd_disposition (code, label, definition) VALUES ('InScope', 'In scope', 'The asset is inside the boundary in a role the kind of the boundary names.');
INSERT INTO bnd_disposition (code, label, definition) VALUES ('Inherited', 'Inherited', 'The asset''s requirements are met by what another party provides, under an inheritance that names the controls.');
INSERT INTO bnd_disposition (code, label, definition) VALUES ('External', 'External', 'The asset stands for a system outside the fleet that the boundary relies on or exchanges information with.');
INSERT INTO bnd_disposition (code, label, definition) VALUES ('OutOfScope', 'Out of scope', 'The asset is outside the boundary by a person''s decision, with a justification, evidence and an expiry.');
INSERT INTO bnd_disposition (code, label, definition) VALUES ('Undecided', 'Undecided', 'No one has decided; every asset has this disposition in a boundary until a person decides, and it is a finding.');
INSERT INTO bnd_impact (code, label, definition) VALUES ('Low', 'Low', 'The loss of the objective would have a limited adverse effect on operations, assets or people.');
INSERT INTO bnd_impact (code, label, definition) VALUES ('Moderate', 'Moderate', 'The loss of the objective would have a serious adverse effect on operations, assets or people.');
INSERT INTO bnd_impact (code, label, definition) VALUES ('High', 'High', 'The loss of the objective would have a severe or catastrophic adverse effect on operations, assets or people.');
INSERT INTO bnd_cmmc_asset_category (code, label, definition) VALUES ('CuiAsset', 'CUI asset', 'An asset that processes, stores or transmits controlled unclassified information.');
INSERT INTO bnd_cmmc_asset_category (code, label, definition) VALUES ('SecurityProtectionAsset', 'Security protection asset', 'An asset that provides security functions or capabilities to the assessment scope.');
INSERT INTO bnd_cmmc_asset_category (code, label, definition) VALUES ('ContractorRiskManagedAsset', 'Contractor risk managed asset', 'An asset that can, but is not meant to, handle controlled unclassified information because of the organization''s policy, procedures and practice.');
INSERT INTO bnd_cmmc_asset_category (code, label, definition) VALUES ('SpecializedAsset', 'Specialized asset', 'An asset that can handle controlled unclassified information but cannot be fully secured: an internet-of-things or operational technology device, government furnished equipment, a restricted system or test equipment.');
INSERT INTO bnd_cmmc_asset_category (code, label, definition) VALUES ('OutOfScopeAsset', 'Out-of-scope asset', 'An asset that cannot handle controlled unclassified information and does not protect the assets that do; the organization is prepared to justify that.');
INSERT INTO bnd_party_role (code, label, definition) VALUES ('Controller', 'Controller', 'The party that decides the purposes and means of processing personal data, alone or with others; a business, a Data Fiduciary or an organization in the words of other regimes.');
INSERT INTO bnd_party_role (code, label, definition) VALUES ('Processor', 'Processor', 'The party that processes personal data on behalf of a controller; a service provider, a contractor, an operador, a data intermediary or a Data Processor in the words of other regimes.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('Fci', 'Federal contract information', 'Information provided by or generated for the Government under a contract that is not meant for public release.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('Cui', 'Controlled unclassified information', 'Information the Government creates or holds, or an entity holds for it, that a law, regulation or Government-wide policy says is handled with safeguarding or dissemination controls.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('Phi', 'Protected health information', 'Individually identifiable health information, in any form or medium, with the exclusions the rule lists.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('Ephi', 'Electronic protected health information', 'The part of protected health information that is transmitted or maintained in electronic media.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('PersonalData', 'Personal data', 'Information about an identified or identifiable natural person, in the words of the privacy regime that governs it.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('SpecialCategoryData', 'Special category data', 'Personal data of the kinds a regime sets apart for stronger protection, such as health, biometric or beliefs.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('CardholderData', 'Cardholder data', 'The data of a payment card that the card brands'' standard requires to be protected.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('SensitiveAuthenticationData', 'Sensitive authentication data', 'The data used to authenticate a cardholder or authorize a card transaction, which must not be kept after authorization.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('SecurityProtectionData', 'Security protection data', 'Data about the protections of an environment: its configuration, logs and credentials.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('Confidential', 'Confidential', 'Information whose disclosure the organization restricts to those who need it.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('Internal', 'Internal', 'Information for the organization''s own use that carries no further restriction.');
INSERT INTO bnd_data_class (code, label, definition) VALUES ('Public', 'Public', 'Information that may be disclosed without restriction.');
